const body = $('Webhook').first().json.body ?? {};

// Generate 30 demo students, each with semesters 1–6
const students = Array.from({ length: 30 }, (_, i) => {
  const number = i + 1;
  const hallTicket = `DEMO2026${String(number).padStart(3, '0')}`;

  return {
    hallTicket,
    name: `Demo Student ${number}`,
    pin: String(1000 + number)
  };
});

const hallTicket = String(body.hallTicket ?? '')
  .trim()
  .toUpperCase();

const pin = String(body.pin ?? '').trim();

if (!hallTicket || !pin) {
  return [{
    json: {
      success: false,
      message: 'Hall ticket and PIN are required'
    }
  }];
}

const student = students.find(
  s => s.hallTicket === hallTicket && s.pin === pin
);

if (!student) {
  return [{
    json: {
      success: false,
      message: 'Invalid hall ticket or PIN'
    }
  }];
}

// Synthetic demo subjects; replace with verified marks data later.
const subjects = [
  { code: '01', name: 'Programming' },
  { code: '02', name: 'Mathematics' },
  { code: '03', name: 'Database Systems' },
  { code: '04', name: 'Computer Networks' },
  { code: '05', name: 'Operating Systems' }
];

const marks = [];

for (let sem = 1; sem <= 6; sem++) {
  for (let j = 0; j < subjects.length; j++) {
    // Deterministic sample marks for the demo
    const internal = 15 + ((student.hallTicket.length + sem + j * 3) % 11);
    const external = 25 + ((Number(student.hallTicket.slice(-3)) + sem * 7 + j * 9) % 51);
    const total = internal + external;

    marks.push({
      semester: sem,
      subjectCode: `S${sem}${subjects[j].code}`,
      subjectName: subjects[j].name,
      internalMarks: internal,
      externalMarks: external,
      totalMarks: total,
      maxMarks: 100,
      grade: total >= 90 ? 'A+' :
             total >= 80 ? 'A' :
             total >= 70 ? 'B' :
             total >= 60 ? 'C' :
             total >= 50 ? 'D' : 'F',
      result: total >= 40 ? 'PASS' : 'FAIL'
    });
  }
}

const summaries = Array.from({ length: 6 }, (_, index) => {
  const semester = index + 1;
  const semesterMarks = marks.filter(m => m.semester === semester);
  const average = semesterMarks.reduce(
    (sum, m) => sum + m.totalMarks, 0
  ) / semesterMarks.length;

  return {
    semester,
    subjectCount: semesterMarks.length,
    averageMarks: Number(average.toFixed(2)),
    sgpa: Number((average / 10).toFixed(2)),
    result: semesterMarks.every(m => m.result === 'PASS')
      ? 'PASS'
      : 'CHECK RESULTS'
  };
});

return [{
  json: {
    success: true,
    message: 'Login successful',
    student: {
      hallTicket: student.hallTicket,
      name: student.name
    },
    results: {
      marks,
      summaries
    }
  }
}];
